use serde::{Deserialize, Serialize};

use crate::models::{FieldError};

/// RFC 9457 problem details error response.
#[derive(Serialize, Deserialize, Debug, Clone, Default)]
pub struct ProblemDetail {
    /// SDKWork machine-readable error code.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub code: Option<String>,

    /// Human-readable explanation specific to this occurrence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,

    /// Field-level validation errors.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub errors: Option<Vec<FieldError>>,

    /// URI reference identifying this occurrence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub instance: Option<String>,

    /// Request identifier for client support and log correlation.
    #[serde(rename = "requestId")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,

    /// HTTP status code generated by the origin server.
    pub status: i64,

    /// Short human-readable problem title.
    pub title: String,

    /// Trace identifier for support and audit correlation.
    #[serde(rename = "traceId")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trace_id: Option<String>,

    /// Problem type URI reference.
    pub r#type: String,
}
